package it.penny.api.mail;
import it.penny.api.PennyApplication;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.*;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.web.context.WebApplicationContext;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.springframework.http.MediaType.APPLICATION_JSON;
@SpringBootTest(classes=PennyApplication.class,properties="penny.trash.cleanup-enabled=false")
@org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable(named="PENNY_TEST_JDBC_URL",matches=".+")
class MailIntegrationTest {
 @DynamicPropertySource static void config(DynamicPropertyRegistry p){p.add("spring.datasource.url",()->System.getenv("PENNY_TEST_JDBC_URL")+"?currentSchema=outlook_mail");p.add("spring.datasource.username",()->System.getenv("PENNY_TEST_DB_USER"));p.add("spring.datasource.password",()->System.getenv("PENNY_TEST_DB_PASSWORD"));p.add("spring.flyway.schemas",()->"outlook_mail");}
 @Autowired JdbcTemplate db;@Autowired WebApplicationContext context;@Autowired ObjectMapper json;MockMvc mvc;
 final UsernamePasswordAuthenticationToken admin=new UsernamePasswordAuthenticationToken("mail@test.invalid","unused");String token;long mailId;
 @BeforeEach void setup()throws Exception{mvc=MockMvcBuilders.webAppContextSetup(context).build();db.execute("TRUNCATE penny_customers,penny_users CASCADE");db.update("INSERT INTO penny_users(email,full_name,password_hash,must_change_password) VALUES (?,'Mail Admin','unused',false)",admin.getName());db.update("INSERT INTO penny_user_roles SELECT u.id,r.id FROM penny_users u CROSS JOIN penny_roles r WHERE u.email=? AND r.code='ADMIN'",admin.getName());db.update("INSERT INTO penny_customers(id,kind,name,email) VALUES (1,'COMPANY','Uno','uno@example.org'),(2,'COMPANY','Due','due@example.org')");var r=mvc.perform(post("/api/mail/connections").principal(admin)).andExpect(status().isOk()).andReturn();token=json.readTree(r.getResponse().getContentAsString()).get("token").asText();}
 Map<String,Object> mail(){return new LinkedHashMap<>(Map.ofEntries(Map.entry("customerId",1),Map.entry("mailbox","me@example.org"),Map.entry("itemId","outlook1"),Map.entry("internetMessageId","<one@example.org>"),Map.entry("conversationId","thread1"),Map.entry("subject","Richiesta licenze"),Map.entry("sender","uno@example.org"),Map.entry("recipients",List.of("me@example.org")),Map.entry("sentAt","2026-11-06T12:00:00Z"),Map.entry("bodyText","Test <script>alert(1)</script>"),Map.entry("originalBase64","ZW1s"),Map.entry("originalKind","EML"),Map.entry("attachments",List.of(Map.of("filename","offerta.pdf","contentBase64","AAEC","inlineImage",false)))));}
 long save()throws Exception{var r=mvc.perform(post("/api/outlook/bridge/messages").header("Authorization","Bearer "+token).contentType(APPLICATION_JSON).content(json.writeValueAsBytes(mail()))).andExpect(status().isOk()).andReturn();return json.readTree(r.getResponse().getContentAsString()).get("id").asLong();}
 @Test void storesOriginalAttachmentsAndDeduplicates()throws Exception{long id=save();assertEquals(id,save());assertEquals(1L,db.queryForObject("SELECT count(*) FROM penny_mail_messages",Long.class));mvc.perform(get("/api/mail/"+id).principal(admin)).andExpect(jsonPath("$.attachments[0].filename").value("offerta.pdf"));long file=db.queryForObject("SELECT id FROM penny_mail_attachments",Long.class);mvc.perform(get("/api/mail/"+id+"/attachments/"+file).principal(admin)).andExpect(content().bytes(new byte[]{0,1,2}));mvc.perform(get("/api/mail/"+id+"/original").principal(admin)).andExpect(content().bytes("eml".getBytes()));}
 @Test void matchesSharedContactsExactlyAndExcludesDeleted()throws Exception{db.update("INSERT INTO penny_customer_contacts(customer_id,full_name,email) VALUES (1,'Shared','shared@example.org')");db.update("INSERT INTO penny_contact_customers(contact_id,customer_id) SELECT id,2 FROM penny_customer_contacts");mvc.perform(post("/api/outlook/bridge/customers").header("Authorization","Bearer "+token).contentType(APPLICATION_JSON).content("{\"emails\":[\" SHARED@example.org \"],\"q\":\"\"}")).andExpect(jsonPath("$.length()").value(2));mvc.perform(post("/api/outlook/bridge/customers").header("Authorization","Bearer "+token).contentType(APPLICATION_JSON).content("{\"emails\":[\"other@example.org\"],\"q\":\"\"}")).andExpect(jsonPath("$.length()").value(0));}
 @Test void invalidFileRollsBackEntireMessage()throws Exception{var mail=mail();mail.put("attachments",List.of(Map.of("filename","bad","contentBase64","!!")));mvc.perform(post("/api/outlook/bridge/messages").header("Authorization","Bearer "+token).contentType(APPLICATION_JSON).content(json.writeValueAsBytes(mail))).andExpect(status().isBadRequest());assertEquals(0L,db.queryForObject("SELECT count(*) FROM penny_mail_messages",Long.class));}
 @Test void revocationExpiryAndPasswordVersionInvalidateConnection()throws Exception{db.update("UPDATE penny_users SET session_version=session_version+1 WHERE email=?",admin.getName());mvc.perform(post("/api/outlook/bridge/messages").header("Authorization","Bearer "+token).contentType(APPLICATION_JSON).content(json.writeValueAsBytes(mail()))).andExpect(status().isUnauthorized());}
 @Test void anonymousCookieOnlyAndInvalidTokenCannotUseBridge()throws Exception{mvc.perform(post("/api/outlook/bridge/messages").principal(admin).contentType(APPLICATION_JSON).content(json.writeValueAsBytes(mail()))).andExpect(status().isUnauthorized());mvc.perform(post("/api/outlook/bridge/customers").header("Authorization","Bearer unknown").contentType(APPLICATION_JSON).content("{\"emails\":[],\"q\":\"Uno\"}")).andExpect(status().isUnauthorized());}
 @Test void disabledOrDeniedUserCannotUseToken()throws Exception{db.update("INSERT INTO penny_user_permissions(user_id,permission_code,effect) SELECT id,'DOCUMENTS_WRITE','DENY' FROM penny_users WHERE email=?",admin.getName());mvc.perform(post("/api/outlook/bridge/messages").header("Authorization","Bearer "+token).contentType(APPLICATION_JSON).content(json.writeValueAsBytes(mail()))).andExpect(status().isForbidden());}
 @Test void searchIncludesCommentsAndAssociationsRespectCustomer()throws Exception{long id=save();mvc.perform(post("/api/mail/"+id+"/comments").principal(admin).contentType(APPLICATION_JSON).content("{\"body\":\"Richiamare venerdì\"}")).andExpect(status().isOk());mvc.perform(get("/api/mail").principal(admin).param("customerId","1").param("q","venerdì")).andExpect(jsonPath("$.total").value(1));long activity=db.queryForObject("INSERT INTO penny_customer_records(customer_id,kind,name,status) VALUES (1,'COMMERCIAL','Follow-up','PLANNED') RETURNING id",Long.class);mvc.perform(post("/api/mail/"+id+"/activities").principal(admin).contentType(APPLICATION_JSON).content("{\"recordId\":"+activity+"}")).andExpect(status().isOk());mvc.perform(get("/api/mail").principal(admin).param("customerId","1").param("recordId",String.valueOf(activity))).andExpect(jsonPath("$.total").value(1));assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->db.update("UPDATE penny_customer_records SET customer_id=2 WHERE id=?",activity));long other=db.queryForObject("INSERT INTO penny_customer_records(customer_id,kind,name,status) VALUES (2,'COMMERCIAL','Altro','PLANNED') RETURNING id",Long.class);mvc.perform(post("/api/mail/"+id+"/activities").principal(admin).contentType(APPLICATION_JSON).content("{\"recordId\":"+other+"}")).andExpect(status().isBadRequest());mvc.perform(delete("/api/mail/"+id+"/activities/"+activity).principal(admin)).andExpect(status().isOk());mvc.perform(get("/api/mail").principal(admin).param("customerId","1").param("recordId",String.valueOf(activity))).andExpect(jsonPath("$.total").value(0));}
 @Test void customerTrashHidesMailAndCannotAcceptWrites()throws Exception{long id=save();db.update("UPDATE penny_customers SET deleted_at=now() WHERE id=1");mvc.perform(get("/api/mail/"+id).principal(admin)).andExpect(status().isNotFound());mvc.perform(post("/api/outlook/bridge/messages").header("Authorization","Bearer "+token).contentType(APPLICATION_JSON).content(json.writeValueAsBytes(mail()))).andExpect(status().isNotFound());}
}
